// architecture-composer sketch for: Universal Program Porting Generator
const comps = [
  { n: 'retrieval', cost: 3, lat: 51 },
  { n: 'reasoning', cost: 13, lat: 664 },
  { n: 'memory', cost: 2, lat: 38 },
  { n: 'tools', cost: 3, lat: 283 },
];
const tot = comps.reduce((a, c) => ({ cost: a.cost + c.cost, lat: a.lat + c.lat }), { cost: 0, lat: 0 });
console.log(JSON.stringify({ components: comps.map(c => c.n), totalCostUnits: tot.cost,
  totalLatencyMs: tot.lat, withinBudget: tot.cost <= 25, feasible: tot.lat <= 2000 }));

